$$\begin{array}{l}
  {A = {\lbrack{{area\ under}y = f{(x)}}\rbrack} - {\lbrack{{area\ under}y = g{(x)}}\rbrack}} \\
  {\phantom{A} = {\int_{a}^{b}{f{(x)}dx -}}\int_{a}^{b}g{(x)}dx = \int_{a}^{b}\lbrack f(x) - g(x)\rbrack dx}
  \end{array}$$

$$\begin{array}{l}
  {V = \int_{- r}^{r}A(x)dx = \int_{- r}^{r}\pi(r^{2} - x^{2})dx} \\
  {\phantom{V} = {2\pi{\int_{0}^{r}{(r^{2} - x^{2})dx}}}\qquad\left( \text{The integrand is even.} \right)} \\
  {\phantom{V} = {2\pi\left\lbrack {r^{2}x - \frac{x^{3}}{3}} \right\rbrack_{0}^{r} = 2\pi\left( {r^{3} - \frac{r^{3}}{3}} \right) = \frac{4}{3}\pi r^{3}}}
  \end{array}$$

$$\begin{array}{l}
  {V = {V_{2} - V_{1}}} \\
  {\phantom{V} = {\pi r_{2}^{2}h - \pi r_{1}^{2}h = \pi\left( {r_{2}^{2} - r_{1}^{2}} \right)h}} \\
  {\phantom{V} = {\pi\left( {r_{2} + r_{1}} \right)\left( {r_{2} - r_{1}} \right)h}} \\
  {\phantom{V} = {2\pi\frac{r_{2} + r_{1}}{2}h\left( {r_{2} - r_{1}} \right)}}
  \end{array}$$

$$\begin{array}{l}
  {W = {\lim\limits_{n\rightarrow\infty}{\sum\limits_{i = 1}^{n}1568}\pi x_{i}^{*}{({10 - x_{i}^{*}})}^{2}\Delta x = \int_{2}^{10}1568}\pi x{({10 - x})}^{2}dx} \\
  {\phantom{W} = {1568\pi\int_{2}^{10}{({100x - 20x^{2} + x^{3}})}}dx = 1568\pi\left\lbrack {50x^{2} - \frac{20x^{3}}{3} + \frac{x^{4}}{4}} \right\rbrack_{2}^{10}} \\
  {\phantom{W} = {1568\pi\left( \frac{2048}{3} \right) \approx 3.4 \times 10^{6}J}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{f(x_{1}^{*}) + \cdot \cdot \cdot + f(x_{n}^{*})}{\frac{b - a}{\Delta x}} = \frac{1}{b - a}\lbrack f(x_{1}^{*}) + \cdot \cdot \cdot + f(x_{n}^{*})\rbrack\Delta x} \\
  {\phantom{\frac{f(x_{1}^{*}) + \cdot \cdot \cdot + f(x_{n}^{*})}{\frac{b - a}{\Delta x}}} = \frac{1}{b - a}\left\lbrack {f{(x_{1}^{*})}\Delta x + \cdot \cdot \cdot + f{(x_{n}^{*})}\Delta x} \right\rbrack} \\
  {\phantom{\frac{f(x_{1}^{*}) + \cdot \cdot \cdot + f(x_{n}^{*})}{\frac{b - a}{\Delta x}}} = \frac{1}{b - a}{\sum\limits_{i = 1}^{n}{f{(x_{i}^{*})}\Delta x}}}
  \end{array}$$

$$\begin{array}{l}
  {\upsilon_{avg} = {\frac{1}{t_{2} - t_{1}}{\int_{t_{1}}^{t_{2}}{\upsilon{(t)}dt = \frac{1}{t_{2} - t_{1}}{\int_{t_{1}}^{t_{2}}{s^{\prime}{(t)}dt}}}}}} \\
  {\phantom{\upsilon_{ave}} = {\frac{1}{t_{2} - t_{1}}\left\lbrack {s\left( t_{2} \right) - s\left( t_{1} \right)} \right\rbrack\qquad\left( \text{by the Net Change Theorem} \right)}} \\
  {\phantom{\upsilon_{ave}} = {\frac{s\left( t_{2} \right) - s\left( t_{1} \right)}{t_{2} - t_{1}} = {average\ velocity}}}
  \end{array}$$
